# spaCy Matcher patterns for Restrictive & Exclusive Constructions
pattern_ne_que = [
    # Pattern 1: Discontinuous ne...que restriction
    [
        {"LOWER": {"IN": ["ne", "n'"]}},
        {"POS": {"IN": ["VERB", "AUX"]}},
        {"OP": "*"},
        {"LOWER": {"IN": ["que", "qu'"]}}
    ],
    # Pattern 2: Ne faire que + Infinitive
    [
        {"LOWER": {"IN": ["ne", "n'"]}},
        {"LEMMA": "faire"},
        {"LOWER": {"IN": ["que", "qu'"]}},
        {"POS": "VERB", "MORPH": {"IS_SUPERSET": ["VerbForm=Inf"]}}
    ],
    # Pattern 3: Adverbial & Prepositional Exclusions (uniquement, seulement, rien que, hormis, excepté, à l'exception de)
    [
        {"LOWER": "rien"},
        {"LOWER": {"IN": ["que", "qu'"]}}
    ],
    [
        {"LOWER": "à"},
        {"LOWER": "l'"},
        {"LOWER": "exception"},
        {"LOWER": "de"}
    ],
    [
        {"LOWER": {"IN": ["uniquement", "seulement", "hormis", "excepté"]}}
    ]
]

# Pattern targeting: si + Subject + Auxiliary(Imparfait) + Past Participle ... Main Verb(Conditionnel Présent)
pattern = [
    # Subordinate marker "si" or "s'"
    {"LOWER": {"IN": ["si", "s'"]}, "POS": "SCONJ"},
    # Optional intervening subject pronoun/noun/adverbs
    {"OP": "*"},
    # Auxiliary in Imparfait (avoir / être)
    {
        "POS": "AUX",
        "LEMMA": {"IN": ["avoir", "être"]},
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Imp"]}
    },
    # Optional adverbs between auxiliary and past participle
    {"POS": "ADV", "OP": "*"},
    # Main verb past participle completing the Plus-que-parfait
    {
        "POS": "VERB",
        "MORPH": {"IS_SUBSET": ["VerbForm=Part", "Tense=Past"]}
    },
    # Intervening clausal text leading to main clause
    {"OP": "*"},
    # Main clause verb or auxiliary in Conditionnel Présent
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IS_SUBSET": ["Mood=Cnd", "Tense=Pres"]}
    }
]
